import{app,BrowserWindow,WebContentsView}from'electron';import{mkdtemp,writeFile}from'node:fs/promises';import{resolve,join}from'node:path';import assert from'node:assert/strict';import{attachPlaywrightView}from'../../packages/browser/src/playwright-view.js';import{UniversalFormSession}from'../../packages/browser/src/universal-form.js';import{overrideProfile as profile,overrideHTML as html}from'./override-profile.js';
const dir=await mkdtemp(resolve('.backups/override-engine-'));app.setPath('userData',dir);await app.whenReady();const w=new BrowserWindow({show:false}),v=new WebContentsView({webPreferences:{partition:'override-test',sandbox:true,contextIsolation:true,nodeIntegration:false,backgroundThrottling:false}});w.contentView.addChildView(v);v.setBounds({x:0,y:0,width:1000,height:800});
try{
 await v.webContents.loadURL('data:text/html;charset=utf-8,'+encodeURIComponent(html));const attached=await attachPlaywrightView(v.webContents),abort=new AbortController();let checks=0;
 const keep=new UniversalFormSession(attached.page,profile,async()=>profile,()=>1,abort.signal,false);let x=await keep.inspect();assert.ok(!x.fields.some(f=>f.ref==='field-0'));checks++;await assert.rejects(keep.act({observation:x.observation,action:'fill',target:'field-0',fact:keep.facts.find(f=>f.kind==='fullName')!.ref}),/PRESERVED/);checks++;keep.close();
 const s=new UniversalFormSession(attached.page,profile,async()=>profile,()=>1,abort.signal);x=await s.inspect();assert.equal(x.overwriteExisting,true);assert.ok(x.fields.some(f=>f.ref==='field-0'&&f.replaceExisting));checks+=2;
 const targets={n:profile.fullName,e:profile.email,c1:'虚构计算学院',c2:'虚构数学学院统计系','role-i':'算法实习生',di:'本地已确认的实习内容。',p1:'DemoAgent｜虚构演示项目',p2:'DemoRL｜虚构演示项目',r1:'主要开发者',r2:'主要负责人',d1:profile.career!.projects[0]!.description,d2:profile.career!.projects[1]!.description};
 // Scripted selection tests host semantics. The separate paid full-App run tests model selection.
 for(let round=0;round<8;round++){x=await s.inspect();const batch=x.fields.filter(f=>f.candidates.length===1&&['text','textarea','email','month'].includes(f.type)).slice(0,12);if(!batch.length)break;const r=await s.fillGroup(x.observation,batch.map(f=>({target:f.ref,fact:f.candidates[0]!})));assert.equal(r.failures.length,0,JSON.stringify(r.failures));}
 for(const[id,value]of Object.entries(targets)){assert.equal(await attached.page.locator('#'+id).inputValue(),value,id);checks++;}
 assert.equal((await s.verify()).pending,0);checks++;assert.equal((await s.inspect()).fields.length,0);checks++;
 for(const[id,value]of Object.entries({ref:'保留',id:'INVALID-ID',password:'fixture-only',captcha:'KEEP'})){assert.equal(await attached.page.locator('#'+id).inputValue(),value);checks++;}
 assert.equal(await attached.page.locator('[type=checkbox]').isChecked(),false);assert.equal(await attached.page.evaluate('window.submits'),0);checks+=2;
 await attached.page.locator('#d1').fill('外部清空后错误内容');const after=await s.verify();assert.ok(after.pending>0);checks++;
 const before=await s.inspect();await attached.page.locator('#d1').fill('外部又改了一次');await assert.rejects(s.act({observation:before.observation,action:'fill',target:before.fields.find(f=>f.label==='项目描述')!.ref,fact:s.facts.find(f=>f.record==='project-1'&&f.kind==='description')!.ref}),/PAGE_CHANGED/);checks++;
 const missingProfile=structuredClone(profile);missingProfile.career!.educations[0]!.college='';await attached.page.locator('#c1').fill('');const missing=new UniversalFormSession(attached.page,missingProfile,async()=>missingProfile,()=>1,abort.signal);const missingView=await missing.inspect();assert.ok(missingView.manualFields.some(f=>f.label==='学院名称'&&f.reason.includes('没有这项')));assert.ok(!missingView.fields.some(f=>f.group==='group-0'&&f.label==='学院名称'));checks+=2;missing.close();
 await attached.page.evaluate("const original=document.querySelectorAll('.form-part')[3];const copy=original.cloneNode(true);copy.querySelectorAll('input,textarea').forEach(e=>e.removeAttribute('id'));copy.querySelectorAll('input')[1].value='';original.after(copy)");const duplicate=new UniversalFormSession(attached.page,profile,async()=>profile,()=>1,abort.signal);const dup=await duplicate.inspect();assert.ok(!dup.fields.some(f=>f.label==='职务'));assert.ok(dup.manualFields.some(f=>f.label==='职务'&&f.reason.includes('重复经历')));checks+=2;duplicate.close();
 abort.abort();await assert.rejects(s.inspect(),/CONTEXT_CHANGED/);checks++;await attached.close();await writeFile(join(dir,'result.json'),JSON.stringify({ok:true,checks,targets:Object.keys(targets).length,apiRequests:0}));console.log(JSON.stringify({overrideSmoke:true,ok:true,checks,targets:Object.keys(targets).length}));v.webContents.close();w.destroy();app.exit(0);
}catch(e){console.error(e);w.destroy();app.exit(1);}
